import type {HandoffScope} from './cashier-handoff';
const object=(v:unknown):Record<string,unknown>=>{if(!v||typeof v!=='object'||Array.isArray(v))throw Error('Invalid opening account.');return v as Record<string,unknown>};
const uuid=(v:unknown):v is string=>typeof v==='string'&&/^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/.test(v);
const amount=(v:unknown):string=>{if(typeof v!=='string'||!/^(0|[1-9][0-9]{0,15})$/.test(v))throw Error('Invalid opening account amount.');return v};
const civilDate=(v:unknown):v is string=>typeof v==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(v)&&Number.isFinite(Date.parse(v+'T00:00:00Z'))&&new Date(v+'T00:00:00Z').toISOString().slice(0,10)===v;
export function readFinancialOpeningAccount(value:unknown,scope:HandoffScope,reservation:string,date:string){
 const v=object(value),categories=['receivable','prepayment','security'] as const;
 if(!civilDate(date)||v.schema_version!==1||v.tenant_id!==scope.tenant||v.property_id!==scope.property||v.actor_id!==scope.actor||v.reservation_id!==reservation||v.as_of!==date||v.currency!=='USD'||v.basis!=='migrated_opening_balances_only'||v.verifies_bank_settlement!==false||v.complete!==true||!Array.isArray(v.rows)||v.rows.length>1000||!Array.isArray(v.activity)||v.activity.length>1000||v.has_openings!==(v.rows.length>0))throw Error('Opening account does not match this reservation and date.');
 let overdue=BigInt(0);const aging={current:BigInt(0),days1to30:BigInt(0),days31to60:BigInt(0),days61to90:BigInt(0),days91plus:BigInt(0)};
 const ids=new Set<string>(),sums={receivable:BigInt(0),prepayment:BigInt(0),security:BigInt(0)};
 const rows=v.rows.map(raw=>{const r=object(raw);if(!uuid(r.id)||ids.has(r.id)||!categories.includes(r.category as typeof categories[number])||typeof r.source_reference!=='string'||!uuid(r.journal_id))throw Error('Invalid opening balance row.');ids.add(r.id);const category=r.category as typeof categories[number],opening=amount(r.opening_minor),applied=amount(r.applied_minor),external=amount(r.external_reduction_minor),remaining=amount(r.remaining_minor);if(BigInt(opening)-BigInt(applied)-BigInt(external)!==BigInt(remaining))throw Error('Opening balance does not reconcile.');sums[category]+=BigInt(remaining);let due:string|null=null,days:number|null=null;if(category==='receivable'){if(!civilDate(r.due_on))throw Error('Invalid receivable due date.');due=r.due_on;days=Math.max(0,(Date.parse(date+'T00:00:00Z')-Date.parse(due+'T00:00:00Z'))/86400000);if(r.overdue_days!==days)throw Error('Overdue days do not match the report date.');const bucket=days===0?'current':days<=30?'days1to30':days<=60?'days31to60':days<=90?'days61to90':'days91plus';aging[bucket]+=BigInt(remaining);if(days>0)overdue+=BigInt(remaining)}else if(r.due_on!==null||r.overdue_days!==null)throw Error('Held funds cannot have receivable aging.');return {id:r.id,category,reference:r.source_reference,opening,applied,external,remaining,due,days,journal:r.journal_id}});
 for(const category of categories)if(amount(object(v.remaining_totals)[category])!==sums[category].toString())throw Error('Opening totals do not reconcile.');
 const events=new Map<string,{id:string;kind:string;date:string;amount:string;source:string;target:string|null;original:string|null;journal:string;reason:string}>(),corrected=new Set<string>();
 const usage=new Map(rows.map(r=>[r.id,{applied:BigInt(0),external:BigInt(0)}]));
 const activity=v.activity.map(raw=>{const e=object(raw);if(!uuid(e.id)||events.has(e.id)||!['invoice_application_correction','invoice_application','application','recorded_collection','recorded_refund','application_correction','external_correction'].includes(e.kind as string)||typeof e.effective_on!=='string'||e.effective_on>date||!uuid(e.source_id)||!ids.has(e.source_id)||e.target_id!==null&&(!uuid(e.target_id)||!ids.has(e.target_id))||e.original_id!==null&&!uuid(e.original_id)||!uuid(e.journal_id)||typeof e.reason!=='string')throw Error('Invalid opening activity.');const row={id:e.id,kind:e.kind as string,date:e.effective_on,amount:amount(e.amount_minor),source:e.source_id,target:e.target_id as string|null,original:e.original_id as string|null,journal:e.journal_id,reason:e.reason};events.set(row.id,row);return row});
 for(const e of activity){const isCorrection=e.kind.endsWith('_correction'),application=e.kind.startsWith('application');if((e.target!==null)!==application||e.target===e.source||BigInt(e.amount)===BigInt(0))throw Error('Invalid opening activity relationship.');if(isCorrection){const original=e.original?events.get(e.original):null;if(!original||corrected.has(original.id)||original.original!==null||original.kind.endsWith('_correction')||original.kind.startsWith('application')!==application||e.kind==='invoice_application_correction'&&original.kind!=='invoice_application'||e.kind==='external_correction'&&!['recorded_collection','recorded_refund'].includes(original.kind)||original.source!==e.source||original.target!==e.target||original.amount!==e.amount||original.date>e.date)throw Error('Correction does not match original activity.');corrected.add(original.id)}else if(e.original!==null)throw Error('Unexpected original activity reference.');const delta=BigInt(e.amount)*(isCorrection?-BigInt(1):BigInt(1));usage.get(e.source)![(application||e.kind.startsWith('invoice_application'))?'applied':'external']+=delta;if(e.target)usage.get(e.target)!.applied+=delta}
 for(const row of rows){const used=usage.get(row.id)!;if(used.applied!==BigInt(row.applied)||used.external!==BigInt(row.external))throw Error('Opening activity does not reconcile to balances.');}
 if(amount(v.overdue_receivable_minor)!==overdue.toString())throw Error('Overdue receivables do not reconcile.');
 return {rows,activity,totals:sums,date,overdue,aging,scope,reservation};
}

export function openingAccountReportRows(report:ReturnType<typeof readFinancialOpeningAccount>){
 const common=['migrated_opening_balances_only',report.scope.tenant,report.scope.property,report.reservation,report.date];
 return [['Basis','Tenant','Property','Reservation','As of','Record type','ID','Category or activity','Reference or reason','Due or activity date','Opening cents','Applied cents','Collected/refunded cents','Remaining cents','Activity cents','Original activity ID','Journal ID'],
 ...report.rows.map(r=>[...common,'balance',r.id,r.category,r.reference,r.due??'',r.opening,r.applied,r.external,r.remaining,'','',r.journal]),
 ...report.activity.map(e=>[...common,'activity',e.id,e.kind,e.reason,e.date,'','','','',e.amount,e.original??'',e.journal]),
 ...Object.entries(report.aging).map(([bucket,total])=>[...common,'receivable_aging','',bucket,'','','','','',total.toString(),'','',''])];
}
